      previo: 'log = """2024-05-01 03:00:01 INFO [ingesta] inicio\n2024-05-01 03:00:05 ERROR [ingesta] timeout al leer s3://lago/raw\n2024-05-01 03:01:00 WARN [dbt] modelo lento\n2024-05-01 03:02:00 ERROR [dbt] test unique falló\nlinea rota sin formato\n2024-05-01 03:03:00 ERROR [ingesta] 401 token vencido\n2024-05-01 03:04:00 ERROR [api] 429 rate limit"""',
